PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS SEARCH_SOURCES (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, domain TEXT NOT NULL, type TEXT NOT NULL, languages_json TEXT NOT NULL DEFAULT '[]', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), quality_weight REAL NOT NULL DEFAULT 0.5 CHECK(quality_weight BETWEEN 0 AND 1), allow_indexing INTEGER NOT NULL DEFAULT 1 CHECK(allow_indexing IN (0,1)), priority INTEGER NOT NULL DEFAULT 0, result_limit INTEGER, accepted_types_json TEXT NOT NULL DEFAULT '[]', config_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(domain, type));
CREATE TABLE IF NOT EXISTS SEARCH_RESULTS (id INTEGER PRIMARY KEY AUTOINCREMENT, external_id TEXT, type TEXT NOT NULL, source TEXT NOT NULL, source_id INTEGER REFERENCES SEARCH_SOURCES(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT, url TEXT NOT NULL, canonical_url TEXT NOT NULL, image_url TEXT, author TEXT, language TEXT, published_at TEXT, duration_seconds INTEGER, tags_json TEXT NOT NULL DEFAULT '[]', level TEXT, materials_json TEXT NOT NULL DEFAULT '[]', metadata_json TEXT NOT NULL DEFAULT '{}', title_hash TEXT NOT NULL, source_quality REAL NOT NULL DEFAULT 0.5, status TEXT NOT NULL DEFAULT 'active', indexed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(canonical_url), UNIQUE(source, external_id));
CREATE INDEX IF NOT EXISTS IDX_SEARCH_RESULTS_LOOKUP ON SEARCH_RESULTS(status, type, language, published_at DESC);
CREATE INDEX IF NOT EXISTS IDX_SEARCH_RESULTS_TITLE_HASH ON SEARCH_RESULTS(title_hash);
CREATE TABLE IF NOT EXISTS SEARCH_QUERIES (id INTEGER PRIMARY KEY AUTOINCREMENT, query_original TEXT NOT NULL, query_normalized TEXT NOT NULL, query_hash TEXT NOT NULL, filters_json TEXT NOT NULL DEFAULT '{}', result_count INTEGER NOT NULL DEFAULT 0, partial INTEGER NOT NULL DEFAULT 0, duration_ms INTEGER, ip_hash TEXT, user_agent_summary TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS IDX_SEARCH_QUERIES_HASH_DATE ON SEARCH_QUERIES(query_hash, created_at DESC);
CREATE TABLE IF NOT EXISTS SEARCH_QUERY_EVENTS (id INTEGER PRIMARY KEY AUTOINCREMENT, query_id INTEGER NOT NULL REFERENCES SEARCH_QUERIES(id) ON DELETE CASCADE, provider TEXT NOT NULL, status TEXT NOT NULL, duration_ms INTEGER, result_count INTEGER NOT NULL DEFAULT 0, discarded_count INTEGER NOT NULL DEFAULT 0, duplicate_count INTEGER NOT NULL DEFAULT 0, cache_status TEXT, error_code TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS SEARCH_CACHE (cache_key TEXT PRIMARY KEY, payload_json TEXT NOT NULL, provider TEXT NOT NULL DEFAULT 'aggregated', expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS IDX_SEARCH_CACHE_EXPIRY ON SEARCH_CACHE(expires_at);
CREATE TABLE IF NOT EXISTS SEARCH_FAVORITES (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, result_id INTEGER NOT NULL REFERENCES SEARCH_RESULTS(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, result_id));
CREATE TABLE IF NOT EXISTS SEARCH_RATINGS (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, result_id INTEGER NOT NULL REFERENCES SEARCH_RESULTS(id) ON DELETE CASCADE, rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, result_id));
CREATE TABLE IF NOT EXISTS SEARCH_BLOCKED_DOMAINS (id INTEGER PRIMARY KEY AUTOINCREMENT, domain TEXT NOT NULL UNIQUE, reason TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS SEARCH_SYNONYMS (id INTEGER PRIMARY KEY AUTOINCREMENT, term TEXT NOT NULL, synonym TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'pt-BR', weight REAL NOT NULL DEFAULT 1.0, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(term, synonym, language));
CREATE TABLE IF NOT EXISTS SEARCH_INDEX_JOBS (id INTEGER PRIMARY KEY AUTOINCREMENT, job_type TEXT NOT NULL, provider TEXT, status TEXT NOT NULL DEFAULT 'queued', cursor TEXT, stats_json TEXT NOT NULL DEFAULT '{}', error_message TEXT, started_at TEXT, finished_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS IDX_SEARCH_INDEX_JOBS_STATUS ON SEARCH_INDEX_JOBS(status, created_at DESC);
CREATE TABLE IF NOT EXISTS SEARCH_AUDIT_LOG (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, before_json TEXT, after_json TEXT, ip_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
